              "title": "[엘프 뷰티 (NYS:ELF)] Rhode만이 희망이다",
              "broker": "키움증권",
              "analyst": "조소정",
              "date": "2026-02-06",
              "summary": "- 미국 화장품 브랜드사. 본업은 성장이 둔화되고 있지만, 인수 브랜드 Rhode가 성장을 견인 중- 향후 주가는 Rhode의 글로벌 채널 확장 속도 및 성과에 따라 달라질 수 있을 듯- 2 월에는 호주, 뉴질랜드 런칭을 시작으로 해외 유통 확대가 본격화될 예정. 주요 채널 내 성과에 주목",
